-- Region targets for the deep muscle map (momentum-muscle-map): which regions of the body each
-- catalog exercise works, and how hard.
--
-- ADDITIVE ONLY: one new table, read-only for signed-in users. No existing table, column, trigger
-- or row changes, so older app builds are unaffected.
--
-- Weights run from 0 to 1 per exercise, and the strongest region of each exercise is exactly 1:
--   0.9-1.0   prime movers
--   0.4-0.7   major synergists
--   0.15-0.3  minor muscles and stabilisers
-- Regions are the map's unsided slugs (the app mirrors or sides them for unilateral work). The
-- generator always writes part-level slugs (for a muscle with a single part, the part slug is the
-- muscle slug), so the rows of several exercises can be summed per region without resolving the
-- map's hierarchy.
--
-- map_id momentum-muscle-map@0.1 = region ids of momentum-muscle-map 0.1.0 (src/data/hierarchy.ts,
-- last changed in commit 6c489ce). Region ids are that library's public API; a map version that
-- renames or removes one gets rows under a new map_id, and these rows stay for builds that still
-- render 0.1.0.
--
-- The seed block is generated by scripts/catalog/region_targets.py from exercise_muscle_targets
-- (RepDB muscle lists: facts only) and scripts/catalog/region_overrides.json (hand-tuned weights).
-- It holds only catalog ids, region slugs and weights, no RepDB text. It is idempotent: rows are
-- upserted and rows of this map_id that are no longer generated are deleted, so a re-run changes
-- nothing. Catalog ids missing from the database are skipped.
--
-- Apply this file on its own with psql (never supabase db push), then record it in
-- supabase_migrations.schema_migrations; see CLAUDE.md.

begin;
set local lock_timeout = '10s';

create table if not exists public.exercise_region_targets (
  catalog_id text         not null references public.exercises_catalog(id) on delete cascade,
  map_id     text         not null,
  region     text         not null
    constraint exercise_region_targets_region_unsided check (region ~ '^[a-z][a-z0-9_]*$' and region !~ '_(left|right)$'),
  weight     numeric(3,2) not null
    constraint exercise_region_targets_weight_range check (weight > 0 and weight <= 1),
  source     text         not null
    constraint exercise_region_targets_source_valid check (source in ('hand', 'rule')),
  primary key (catalog_id, map_id, region)
);

comment on table public.exercise_region_targets is 'Regions of a body-map renderer that each catalog exercise works, with weights. Generated by scripts/catalog/region_targets.py.';
comment on column public.exercise_region_targets.catalog_id is 'Catalog exercise.';
comment on column public.exercise_region_targets.map_id is 'Renderer and version whose region ids these are, e.g. momentum-muscle-map@0.1.';
comment on column public.exercise_region_targets.region is 'Unsided region slug of that map, at part or muscle level (e.g. pectoralis_major_clavicular). Never a non-muscle region.';
comment on column public.exercise_region_targets.weight is 'How hard the exercise works the region, 0-1; the strongest region of each exercise is 1. Prime movers 0.9-1, major synergists 0.4-0.7, minor/stabilisers 0.15-0.3.';
comment on column public.exercise_region_targets.source is 'hand = tuned by hand (scripts/catalog/region_overrides.json); rule = derived from exercise_muscle_targets plus name keyword rules.';

-- ─── RLS: readable by signed-in users, written by the service role only (as exercise_muscle_targets) ───
alter table public.exercise_region_targets enable row level security;

drop policy if exists "Allow authenticated read access" on public.exercise_region_targets;
create policy "Allow authenticated read access" on public.exercise_region_targets for select to authenticated using (true);

-- TRUNCATE is not covered by RLS.
revoke insert, update, delete, truncate on public.exercise_region_targets from anon, authenticated;

-- ─── Seed ────────────────────────────────────────────────────────────────
-- BEGIN GENERATED SEED (scripts/catalog/region_targets.py; do not edit by hand)
-- 759 exercises (165 hand, 594 rule), 7784 rows, map momentum-muscle-map@0.1 (hierarchy.ts as of commit 6c489ce).
create temp table _region_seed (catalog_id text primary key, source text not null, regions jsonb not null)
  on commit drop;

select s.catalog_id, 'momentum-muscle-map@0.1', r.key, r.value::numeric(3,2), s.source
from _region_seed s
join public.exercises_catalog c on c.id = s.catalog_id
cross join lateral jsonb_each_text(s.regions) r
on conflict (catalog_id, map_id, region) do update
  set weight = excluded.weight, source = excluded.source
  where (exercise_region_targets.weight, exercise_region_targets.source)
        is distinct from (excluded.weight, excluded.source);

-- Rows of this map_id that are no longer generated.
delete from public.exercise_region_targets t
where t.map_id = 'momentum-muscle-map@0.1'
  and not exists (select 1 from _region_seed s where s.catalog_id = t.catalog_id and s.regions ? t.region);
-- END GENERATED SEED

commit;
